INSERT INTO public.nc_compounds (id, name, class, sequence_composition, amino_acid_composition, molecular_formula, monoisotopic_mass, mz_1plus, mz_2plus, cas_number, dad_primary, dad_secondary, dad_guidance, key_chromophores, form_notes, review_flag, source_url) VALUES ('d81fa563-286b-5cc9-bf05-810e0c6af14c', '5 Amino 1MQ', 'Small molecule / quinolinium salt', 'N/A', NULL, 'C10H11IN2', 285.99669636339, 287.00397283001104, 144.005624648316, '42464-96-0', 'Full scan 200-400', '254 (screening)', 'Do not hard-code identity to one wavelength; build a reference DAD spectrum and use spectral match + RT.', 'aromatic/heterocyclic chromophore', '5-amino-1-methylquinolinium iodide; the covalent analyte is the quinolinium cation and the iodide is a counterion.', 'Identity/form review', 'https://precision.fda.gov/ginas/app/ui/substances/244e5c81-594e-4721-b7cd-6dfdf4f068e0');
INSERT INTO public.nc_compounds (id, name, class, sequence_composition, amino_acid_composition, molecular_formula, monoisotopic_mass, mz_1plus, mz_2plus, cas_number, dad_primary, dad_secondary, dad_guidance, key_chromophores, form_notes, review_flag, source_url) VALUES ('decef310-2bb6-536e-8086-b88fbf3f0146', 'AOD-9604', 'Peptide', 'YLRIVQCRSVEGSCGF', 'R2, C2, E1, Q1, G2, I1, L1, F1, S2, Y1, V2', 'C78H123N23O23S2', 1813.86035966509, 1814.8676361317112, 907.937456299166, '221231-10-3', '214', '275-280', 'Peptide-bond signal at 214 nm; Tyr contributes around 275-280 nm.', 'peptide bonds + Tyr', '16-residue peptide; intramolecular disulfide between Cys7 and Cys14.', NULL, 'https://pubchem.ncbi.nlm.nih.gov/compound/AOD-9604');
INSERT INTO public.nc_compounds (id, name, class, sequence_composition, amino_acid_composition, molecular_formula, monoisotopic_mass, mz_1plus, mz_2plus, cas_number, dad_primary, dad_secondary, dad_guidance, key_chromophores, form_notes, review_flag, source_url) VALUES ('580ca3e9-9f03-5d6e-aa8f-4b7e9081e6bb', 'BPC-157 AC', 'Peptide / acetate form', 'GEPPPGKPADDAGLV', 'A2, D2, E1, G3, L1, K1, P4, V1', 'C62H98N16O22', 1418.70415885996, 1419.711435326581, 710.359355896601, '137525-51-0', '214', 'none / full scan', 'Primarily peptide-bond absorbance; little selective aromatic signal above ~230 nm.', 'peptide bonds', 'Formula is the BPC-157 peptide moiety. "AC" is treated here as acetate/counterion form; salt stoichiometry can vary and should be recorded lot-by-lot.', 'Identity/form review', 'https://pubchem.ncbi.nlm.nih.gov/compound/BPC-157');
INSERT INTO public.nc_compounds (id, name, class, sequence_composition, amino_acid_composition, molecular_formula, monoisotopic_mass, mz_1plus, mz_2plus, cas_number, dad_primary, dad_secondary, dad_guidance, key_chromophores, form_notes, review_flag, source_url) VALUES ('1a6b9a4a-4c6a-5e04-9da5-d91e0058ff59', 'BPC-157 Arginate', 'Peptide / arginate form', 'GEPPPGKPADDAGLV', 'A2, D2, E1, G3, L1, K1, P4, V1', 'C62H98N16O22', 1418.70415885996, 1419.711435326581, 710.359355896601, '137525-51-0', '214', 'none / full scan', 'Primarily peptide-bond absorbance; little selective aromatic signal above ~230 nm.', 'peptide bonds', 'Formula is the BPC-157 peptide moiety. Arginate is a counterion/adduct form and should not be conflated with a covalent change in the peptide.', 'Identity/form review', 'https://pubchem.ncbi.nlm.nih.gov/compound/BPC-157');
INSERT INTO public.nc_compounds (id, name, class, sequence_composition, amino_acid_composition, molecular_formula, monoisotopic_mass, mz_1plus, mz_2plus, cas_number, dad_primary, dad_secondary, dad_guidance, key_chromophores, form_notes, review_flag, source_url) VALUES ('0b759014-c7bb-5889-ac22-9d91db3a48bb', 'Bronchogen', 'Tetrapeptide bioregulator', 'AEDL', 'A1, D1, E1, L1', 'C18H30N4O9', 446.20127856075, 447.208555027371, 224.10791574699599, NULL, '214', 'none / full scan', 'Primarily peptide-bond absorbance; little selective aromatic signal above ~230 nm.', 'peptide bonds', 'Sequence commonly represented as Ala-Glu-Asp-Leu (AEDL); older literature/vendor naming can be inconsistent.', NULL, 'https://pubchem.ncbi.nlm.nih.gov/compound/11690869');
INSERT INTO public.nc_compounds (id, name, class, sequence_composition, amino_acid_composition, molecular_formula, monoisotopic_mass, mz_1plus, mz_2plus, cas_number, dad_primary, dad_secondary, dad_guidance, key_chromophores, form_notes, review_flag, source_url) VALUES ('d9ac967f-43a4-5222-9255-04e928fabace', 'Cagrilintide', 'Modified acylated peptide', 'KCNTATCATQRLAEFLRHSSNNFGPILPPTNVGSNTP', 'A3, R2, N5, C2, E1, Q1, G2, H1, I1, L3, K1, F2, P4, S3, T5, V1', 'C194H312N54O59S2', 4406.25151119841, 4407.258787665031, 2204.1330320658262, '1415456-99-3', '214', '257', 'Peptide-bond signal at 214 nm; Phe absorption near ~257 nm is weak but can discriminate fragments with fewer peptide bonds.', 'peptide bonds + Phe', 'Long-acting amylin analogue; C-terminal amide, Cys2-Cys7 disulfide, and C20 diacid acylation/linker chemistry. FDA GSRS has an estimated O58 formula while PubChem reports O59; this workbook uses PubChem O59 and flags the discrepancy.', 'Formula source discrepancy O58/O59', 'https://pubchem.ncbi.nlm.nih.gov/compound/Cagrilintide');
INSERT INTO public.nc_compounds (id, name, class, sequence_composition, amino_acid_composition, molecular_formula, monoisotopic_mass, mz_1plus, mz_2plus, cas_number, dad_primary, dad_secondary, dad_guidance, key_chromophores, form_notes, review_flag, source_url) VALUES ('9ee7d15a-17fa-57ff-bf13-fd1d38656e7d', 'Cardiogen', 'Tetrapeptide bioregulator', 'AEDR', 'A1, R1, D1, E1', 'C18H31N7O9', 489.21832560627, 490.22560207289104, 245.616439269756, '857267-11-9', '214', 'none / full scan', 'Primarily peptide-bond absorbance; little selective aromatic signal above ~230 nm.', 'peptide bonds', 'Ala-Glu-Asp-Arg (AEDR).', NULL, 'https://www.medchemexpress.com/cardiogen.html');
