INSERT INTO public.nc_compounds (id, name, class, sequence_composition, amino_acid_composition, molecular_formula, monoisotopic_mass, mz_1plus, mz_2plus, cas_number, dad_primary, dad_secondary, dad_guidance, key_chromophores, form_notes, review_flag, source_url) VALUES ('c93644c4-62bf-529e-921b-e5890d20d2a0', 'Tesamorelin', 'Modified GHRH analogue', 'YADAIFTNSYRKVLGQLSARKLLQDIMSRQQGESNQERGARARL-NH2', 'A5, R6, N3, D2, E2, Q5, G3, H1, I2, L5, K2, M1, F1, S4, T1, Y2, V1', 'C221H366N72O67S', 5132.71664080073, 5133.723917267351, 2567.365596866986, '218949-48-5', '214', '275-280', 'Peptide-bond signal at 214 nm; Tyr contributes around 275-280 nm.', 'peptide bonds + Tyr', '44-residue GHRH analogue with N-terminal trans-3-hexenoyl group and C-terminal amide; contains Met, Tyr, Asn and Gln.', NULL, 'https://pubchem.ncbi.nlm.nih.gov/compound/Tesamorelin');
