INSERT INTO public.nc_compounds (id, name, class, sequence_composition, amino_acid_composition, molecular_formula, monoisotopic_mass, mz_1plus, mz_2plus, cas_number, dad_primary, dad_secondary, dad_guidance, key_chromophores, form_notes, review_flag, source_url) VALUES ('756f30dc-ab32-5c83-9eb9-237b0180bb4c', 'Vesilute', 'Dipeptide bioregulator', 'ED', 'D1, E1', 'C9H14N2O7', 262.08010079707003, 263.08737726369105, 132.047326865156, NULL, '214', 'none / full scan', 'Primarily peptide-bond absorbance; little selective aromatic signal above ~230 nm.', 'peptide bonds', 'Commonly represented as Glu-Asp (ED); verify supplier identity because the trade name has limited authoritative database coverage.', 'Identity/form review', 'https://pubchem.ncbi.nlm.nih.gov/#query=Glu-Asp');
