INSERT INTO public.nc_impurity_candidates (nc_compound_id, impurity_code, name, category, evidence_level, formation_pathway, structure_change, molecular_formula, formula_delta, monoisotopic_mass, mass_delta, mz_1plus, mz_2plus, dad_primary, dad_secondary, dad_discriminator, rp_hplc_behavior, lc_ms_discriminator, likely_trigger, source_url, notes) VALUES ('d81fa563-286b-5cc9-bf05-810e0c6af14c', '5AMINO1MQ-001', '5-amino-1-methylquinolinium cation (counterion-free representation)', 'Identity/form ambiguity', 'Reported/known', 'Salt/counterion dissociation or alternative material form', 'Remove iodide counterion; covalent cation unchanged', 'C10H11N2', NULL, 159.0922234, -126.904473, 160.0994998, 80.55338815, 'Full scan 200-400', '254 (screening)', 'DAD spectrum should match the iodide form because the covalent chromophore is unchanged', 'Usually very similar after dissolution; counterion may alter sample solvent/peak shape', 'Exact mass delta -126.904473 Da', 'Storage stress, pH, oxygen/light, synthesis history, or sample-prep conditions depending on pathway', 'https://precision.fda.gov/ginas/app/ui/substances/6f07ddfc-fdef-4319-b81f-3614668ce23c', 'Candidate library entry; DAD+RT supports a hypothesis but does not by itself prove structure.');
