INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, formula_delta, mass_delta, rp_hplc_behavior, dad_behavior, evidence_level, source_url, notes) VALUES ('PEP-DEAM', 'impurity', 'Peptides', 'Asn/Gln', 'Deamidation', 'H-1 N-1 O+1', 0.98401558, 'Often slightly earlier; multiple isomers', 'Usually minimal DAD change', 'Strongly plausible', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10056213/', 'Asn deamidation can produce Asp/isoAsp forms with same +0.984 mass.');
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, formula_delta, mass_delta, rp_hplc_behavior, dad_behavior, evidence_level, source_url, notes) VALUES ('PEP-AMIDE-OH', 'impurity', 'C-terminally amidated peptides', 'C-terminal -CONH2', 'C-terminal amide hydrolysis', 'H-1 N-1 O+1', 0.98401558, 'Often slightly earlier', 'Usually minimal DAD change', 'Strongly plausible', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10056213/', 'Same elemental delta as deamidation; site assignment needs MS/MS/reference.');
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, formula_delta, mass_delta, rp_hplc_behavior, dad_behavior, evidence_level, source_url, notes) VALUES ('PEP-PYRO-E', 'impurity', 'Peptides', 'N-terminal Glu', 'Pyroglutamate cyclization from Glu', 'H-2 O-1', -18.01056468, 'Often later / more hydrophobic', 'Usually similar DAD', 'Strongly plausible', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10056213/', 'Blocks N-terminus.');
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, formula_delta, mass_delta, rp_hplc_behavior, dad_behavior, evidence_level, source_url, notes) VALUES ('PEP-PYRO-Q', 'impurity', 'Peptides', 'N-terminal Gln', 'Pyroglutamate cyclization from Gln', 'H-3 N-1', -17.0265491, 'Often later / more hydrophobic', 'Usually similar DAD', 'Strongly plausible', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10056213/', 'Loss of ammonia.');
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, formula_delta, mass_delta, rp_hplc_behavior, dad_behavior, evidence_level, source_url, notes) VALUES ('PEP-SS-RED', 'impurity', 'Disulfide peptides', 'Cys-Cys disulfide', 'Disulfide reduction', 'H+2', 2.01565006, 'Variable; often shape/RT changes', 'Usually similar DAD', 'Strongly plausible', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10056213/', 'One disulfide reduced.');
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, formula_delta, mass_delta, rp_hplc_behavior, dad_behavior, evidence_level, source_url, notes) VALUES ('PEP-SS-SCR', 'impurity', 'Disulfide peptides', '2+ cysteine residues', 'Disulfide scramble', 'same mass', 0.0, 'Separate peak possible', 'Usually similar DAD', 'Strongly plausible', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10056213/', 'Same exact mass; structure/RT/MSMS needed.');
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, formula_delta, mass_delta, rp_hplc_behavior, dad_behavior, evidence_level, source_url, notes) VALUES ('PEP-ASP-ISO', 'impurity', 'Peptides', 'Asp, especially labile local motifs', 'Asp/isoAsp/racemization family', 'same mass', 0.0, 'Nearby peaks/shoulders possible', 'Usually similar DAD', 'Generic chemistry candidate', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10056213/', 'Succinimide intermediate can show -H2O.');
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, formula_delta, mass_delta, rp_hplc_behavior, dad_behavior, evidence_level, source_url, notes) VALUES ('PEP-NAC', 'impurity', 'Peptides', 'N-terminus', 'N-acetylation', 'C+2 H+2 O+1', 42.01056468, 'Usually later / more hydrophobic', 'DAD mostly unchanged', 'Synthesis-related impurity', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10056213/', 'Common synthetic/processing variant.');
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, formula_delta, mass_delta, rp_hplc_behavior, dad_behavior, evidence_level, source_url, notes) VALUES ('PEP-NDEAC', 'impurity', 'N-acetylated peptides', 'N-acetyl terminus', 'N-deacetylated form', 'C-2 H-2 O-1', -42.01056468, 'Usually earlier / more polar', 'DAD mostly unchanged', 'Synthesis/degradation candidate', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10056213/', 'Mass delta is highly diagnostic.');
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, formula_delta, mass_delta, rp_hplc_behavior, dad_behavior, evidence_level, source_url, notes) VALUES ('PEP-CLEAVE', 'impurity', 'Peptides', 'Any peptide bond; Asp-Pro/Ser-adjacent sites can be more labile', 'Backbone hydrolysis / truncation', 'site-specific', NULL, 'Usually smaller fragments elute earlier, but not always', 'Depends on retained aromatic residues', 'Generic chemistry candidate', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10056213/', 'Use exact fragment formula once cleavage site is proposed.');
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, formula_delta, mass_delta, rp_hplc_behavior, dad_behavior, evidence_level, source_url, notes) VALUES ('LIPID-DEACYL', 'impurity', 'Lipidated peptides', 'Fatty-acid linker', 'Deacylated / side-chain-loss species', 'site-specific', NULL, 'Usually much earlier on RP-HPLC', 'Backbone DAD often similar', 'Strongly plausible', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10056213/', 'High-value rule for semaglutide/tirzepatide/retatrutide/cagrilintide.');
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, formula_delta, mass_delta, rp_hplc_behavior, dad_behavior, evidence_level, source_url, notes) VALUES ('SM-OX', 'impurity', 'Small molecules', 'Oxidizable heteroatom/benzylic/aromatic site', 'Oxidation/hydroxylation', 'O+1', 15.99491462, 'Often earlier / more polar', 'Full DAD spectrum may shift', 'Generic chemistry candidate', 'https://pubmed.ncbi.nlm.nih.gov/24065593/', 'Site-specific structure must be confirmed.');
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, formula_delta, mass_delta, rp_hplc_behavior, dad_behavior, evidence_level, source_url, notes) VALUES ('SM-ISO', 'impurity', 'Chiral / E-Z small molecules', 'Stereocenter or alkene', 'Stereoisomer / geometric isomer', 'same mass', 0.0, 'Can be separate RP peak (diastereomer/E-Z); enantiomer may coelute', 'DAD usually same or subtly different', 'Synthesis-related impurity', 'https://admin.ich.org/page/quality-guidelines', 'Do not reject same-mass candidates solely because MS matches parent.');
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, formula_delta, mass_delta, rp_hplc_behavior, dad_behavior, evidence_level, source_url, notes) VALUES ('SALT-FORM', 'impurity', 'Salts/coordination complexes', 'Counterion / metal complex', 'Salt/speciation/form difference', 'form-specific', NULL, 'RT may be similar or change due to solvent/speciation', 'Covalent chromophore may be same; metal complexes can differ strongly', 'Identity/form ambiguity', 'https://precision.fda.gov/', 'Track analyte moiety separately from counterion/metal stoichiometry.');
INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('d81fa563-286b-5cc9-bf05-810e0c6af14c', '5AMINO1MQ-OLG-01', 'ESI noncovalent homodimer / source cluster', 'MS source/association artifact candidate', '2M', 'Instrumental possibility', 'Nonspecific or specific noncovalent association during electrospray/desolvation; may not exist as a discrete solution impurity.', 'Any analyte; risk increases with concentration and soft-source conditions.', NULL, NULL, 0.000000, NULL, NULL, '[2M+Na]+ = 2M + 22.989218 Da; note [2M+2H]2+ lands at the same nominal m/z as monomer [M+H]+ but has z=2 isotope spacing.', 'Same chromophore; if source-generated there is no independent DAD peak and normalized spectrum is identical to monomer.', 'Require chromatographic evidence. Exact coelution with monomer + identical DAD + source/dilution sensitivity strongly favors an ESI cluster rather than a stored dimer.', 'Usually no separate LC peak if formed in the source.', 'Dilution series and source-energy/CID challenge; SEC only if solution oligomer is suspected.', 'Check coelution/peak shape, isotope spacing, charge state, and whether cluster intensity falls disproportionately after dilution or stronger source declustering.', 'For fixed-charge salts/coordination complexes, generic neutral-parent 2M arithmetic is intentionally suppressed; define the actual ionized moiety/speciation first. Do not label a 2M ion as a degradation dimer unless it has independent chromatographic/solution evidence.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4165458/', '5-amino-1MQ is a fixed-charge quinolinium salt and GHK-Cu is a coordination complex; source-cluster ion formulas are speciation-dependent. This is a high-priority false-positive guardrail for the LIMS.');
INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('decef310-2bb6-536e-8086-b88fbf3f0146', 'AOD9604-OLG-01', 'ESI noncovalent homodimer / source cluster', 'MS source/association artifact candidate', '2M', 'Instrumental possibility', 'Nonspecific or specific noncovalent association during electrospray/desolvation; may not exist as a discrete solution impurity.', 'Any analyte; risk increases with concentration and soft-source conditions.', 'C156H246N46O46S4', 3627.720719, 0.000000, 3628.727996, 1814.867636, '[2M+Na]+ = 2M + 22.989218 Da; note [2M+2H]2+ lands at the same nominal m/z as monomer [M+H]+ but has z=2 isotope spacing.', 'Same chromophore; if source-generated there is no independent DAD peak and normalized spectrum is identical to monomer.', 'Require chromatographic evidence. Exact coelution with monomer + identical DAD + source/dilution sensitivity strongly favors an ESI cluster rather than a stored dimer.', 'Usually no separate LC peak if formed in the source.', 'Dilution series and source-energy/CID challenge; SEC only if solution oligomer is suspected.', 'Check coelution/peak shape, isotope spacing, charge state, and whether cluster intensity falls disproportionately after dilution or stronger source declustering.', 'Do not label a 2M ion as a degradation dimer unless it has independent chromatographic/solution evidence.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4165458/', 'This is a high-priority false-positive guardrail for the LIMS.');
INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('decef310-2bb6-536e-8086-b88fbf3f0146', 'AOD9604-OLG-02', 'Solution-phase noncovalent dimer / low-MW oligomer / aggregate', 'Physical association', '2M to nM', 'Generic chemistry candidate', 'Hydrophobic, electrostatic, H-bonding, pi-stacking, lipid-chain association, or fibrillation/self-assembly.', 'Longer peptide, high concentration, hydrophobic/aromatic sequence, lipidation/acylation, agitation, interfaces, pH/ionic-strength stress.', NULL, NULL, NULL, NULL, NULL, 'Native/native-like MS may show nM charge-state series; denaturing RP-LC-MS can dissociate the assembly.', 'Usually very similar normalized DAD spectrum because the covalent chromophores are unchanged. Large particles can create broad long-wavelength apparent absorbance/scattering.', 'Track full-spectrum similarity plus A400/A214 (or long-wave baseline) as a scattering sentinel, but do not use DAD alone to prove oligomerization.', 'May broaden, adsorb, disappear, or dissociate under RP conditions; a discrete RP peak is not guaranteed.', 'SEC (preferably SEC-MALS), DLS, AUC, native MS, or other size-based method.', 'A native-like nM series supports association; disappearance under denaturing LC argues noncovalent rather than covalent.', 'RP-HPLC can under-report noncovalent aggregates because the mobile phase itself may dissociate them.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5665799/', 'Peptide aggregation propensity is highly sequence-, concentration-, pH-, interface-, and formulation-dependent.');
INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('decef310-2bb6-536e-8086-b88fbf3f0146', 'AOD9604-OLG-03', 'Oxidative Tyr-Tyr covalent dimer (dityrosine-like crosslink)', 'Covalent oxidative dimer', '2M-H2', 'Generic chemistry candidate', 'Oxidative phenolic radical coupling between Tyr residues on two molecules.', 'At least one Tyr plus oxidative/light/peroxide/metal stress.', 'C156H244N46O46S4', 3625.705069, -2.015650, 3626.712346, 1813.859811, 'Exact mass alone cannot distinguish dityrosine from other 2H-loss crosslinks; MS/MS localization is needed.', 'Altered: dityrosine-type chemistry can introduce new near-UV absorbance not present in the monomer.', 'High-value DAD clue: new bands near ~290 and ~315 nm in documented Tyr-peptide dimer systems. Track A315/A280 and A315/A214 plus full-spectrum shape.', 'Often more retained/broader due to doubled molecular size and hydrophobic surface, but method-dependent.', 'LC-HRMS/MS plus reduction-insensitive behavior; fluorescence can be highly sensitive for dityrosine if available.', 'Look for ~2M-H2 neutral mass and crosslink-localizing MS/MS fragments.', 'A 2M-H2 mass without the spectral/fragment evidence is not sufficient; disulfide or other oxidative crosslinks can have the same net 2H loss.', 'https://pubmed.ncbi.nlm.nih.gov/1863276/', 'The 290/315-nm clue is mechanism-level evidence from Tyr-containing systems, not a compound-specific occurrence claim.');
INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('decef310-2bb6-536e-8086-b88fbf3f0146', 'AOD9604-OLG-04', 'Intermolecular disulfide-linked dimer after disulfide opening/scrambling', 'Covalent disulfide dimer', '2M-H2', 'Strongly plausible', 'Reduction/opening of the native intramolecular disulfide followed by intermolecular disulfide pairing or scrambling.', 'Cys-containing peptide with an intramolecular disulfide; redox stress, pH, thiols, metals, or manufacturing conditions.', 'C156H244N46O46S4', 3625.705069, -2.015650, 3626.712346, 1813.859811, 'Reduction with DTT/TCEP should collapse the disulfide-linked dimer; same net 2H-loss mass as other oxidative dimers requires this challenge/MSMS.', 'Usually near-parent normalized spectrum because chromophores are unchanged.', 'DAD primarily confirms cochromophore identity; full-spectrum similarity to monomer is expected unless conformation/oxidation also changed.', 'Often later/broader; may show multiple scrambled isomers.', 'Reducing-agent challenge + LC-HRMS/MS; SEC can quantify size species.', 'Look for ~2M-H2 mass and reduction sensitivity.', 'A 2M-H2 peak that is reduction-insensitive should push dityrosine/other crosslink hypotheses higher.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10056213/', 'Parent contains a native intramolecular disulfide; intermolecular dimer requires bond rearrangement rather than simple oxidation of two free thiols.');
INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('580ca3e9-9f03-5d6e-aa8f-4b7e9081e6bb', 'BPC157AC-OLG-01', 'ESI noncovalent homodimer / source cluster', 'MS source/association artifact candidate', '2M', 'Instrumental possibility', 'Nonspecific or specific noncovalent association during electrospray/desolvation; may not exist as a discrete solution impurity.', 'Any analyte; risk increases with concentration and soft-source conditions.', 'C124H196N32O44', 2837.408318, 0.000000, 2838.415594, 1419.711435, '[2M+Na]+ = 2M + 22.989218 Da; note [2M+2H]2+ lands at the same nominal m/z as monomer [M+H]+ but has z=2 isotope spacing.', 'Same chromophore; if source-generated there is no independent DAD peak and normalized spectrum is identical to monomer.', 'Require chromatographic evidence. Exact coelution with monomer + identical DAD + source/dilution sensitivity strongly favors an ESI cluster rather than a stored dimer.', 'Usually no separate LC peak if formed in the source.', 'Dilution series and source-energy/CID challenge; SEC only if solution oligomer is suspected.', 'Check coelution/peak shape, isotope spacing, charge state, and whether cluster intensity falls disproportionately after dilution or stronger source declustering.', 'Do not label a 2M ion as a degradation dimer unless it has independent chromatographic/solution evidence.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4165458/', 'This is a high-priority false-positive guardrail for the LIMS.');
