INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('d9ac967f-43a4-5222-9255-04e928fabace', 'CAGRILINTIDE-OLG-02', 'Solution-phase noncovalent dimer / low-MW oligomer / aggregate', 'Physical association', '2M to nM', 'Strongly plausible', 'Hydrophobic, electrostatic, H-bonding, pi-stacking, lipid-chain association, or fibrillation/self-assembly.', 'Longer peptide, high concentration, hydrophobic/aromatic sequence, lipidation/acylation, agitation, interfaces, pH/ionic-strength stress.', NULL, NULL, NULL, NULL, NULL, 'Native/native-like MS may show nM charge-state series; denaturing RP-LC-MS can dissociate the assembly.', 'Usually very similar normalized DAD spectrum because the covalent chromophores are unchanged. Large particles can create broad long-wavelength apparent absorbance/scattering.', 'Track full-spectrum similarity plus A400/A214 (or long-wave baseline) as a scattering sentinel, but do not use DAD alone to prove oligomerization.', 'May broaden, adsorb, disappear, or dissociate under RP conditions; a discrete RP peak is not guaranteed.', 'SEC (preferably SEC-MALS), DLS, AUC, native MS, or other size-based method.', 'A native-like nM series supports association; disappearance under denaturing LC argues noncovalent rather than covalent.', 'RP-HPLC can under-report noncovalent aggregates because the mobile phase itself may dissociate them.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5665799/', 'Lipidated/acylated therapeutic peptides deserve a higher physical-self-association prior; exact behavior must be established empirically for the specific compound/formulation.');
INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('d9ac967f-43a4-5222-9255-04e928fabace', 'CAGRILINTIDE-OLG-03', 'Intermolecular disulfide-linked dimer after disulfide opening/scrambling', 'Covalent disulfide dimer', '2M-H2', 'Strongly plausible', 'Reduction/opening of the native intramolecular disulfide followed by intermolecular disulfide pairing or scrambling.', 'Cys-containing peptide with an intramolecular disulfide; redox stress, pH, thiols, metals, or manufacturing conditions.', 'C388H622N108O118S4', 8810.487372, -2.015650, 8811.494649, 4406.250963, 'Reduction with DTT/TCEP should collapse the disulfide-linked dimer; same net 2H-loss mass as other oxidative dimers requires this challenge/MSMS.', 'Usually near-parent normalized spectrum because chromophores are unchanged.', 'DAD primarily confirms cochromophore identity; full-spectrum similarity to monomer is expected unless conformation/oxidation also changed.', 'Often later/broader; may show multiple scrambled isomers.', 'Reducing-agent challenge + LC-HRMS/MS; SEC can quantify size species.', 'Look for ~2M-H2 mass and reduction sensitivity.', 'A 2M-H2 peak that is reduction-insensitive should push dityrosine/other crosslink hypotheses higher.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10056213/', 'Parent contains a native intramolecular disulfide; intermolecular dimer requires bond rearrangement rather than simple oxidation of two free thiols.');
INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('9ee7d15a-17fa-57ff-bf13-fd1d38656e7d', 'CARDIOGEN-OLG-01', 'ESI noncovalent homodimer / source cluster', 'MS source/association artifact candidate', '2M', 'Instrumental possibility', 'Nonspecific or specific noncovalent association during electrospray/desolvation; may not exist as a discrete solution impurity.', 'Any analyte; risk increases with concentration and soft-source conditions.', 'C36H62N14O18', 978.436651, 0.000000, 979.443928, 490.225602, '[2M+Na]+ = 2M + 22.989218 Da; note [2M+2H]2+ lands at the same nominal m/z as monomer [M+H]+ but has z=2 isotope spacing.', 'Same chromophore; if source-generated there is no independent DAD peak and normalized spectrum is identical to monomer.', 'Require chromatographic evidence. Exact coelution with monomer + identical DAD + source/dilution sensitivity strongly favors an ESI cluster rather than a stored dimer.', 'Usually no separate LC peak if formed in the source.', 'Dilution series and source-energy/CID challenge; SEC only if solution oligomer is suspected.', 'Check coelution/peak shape, isotope spacing, charge state, and whether cluster intensity falls disproportionately after dilution or stronger source declustering.', 'Do not label a 2M ion as a degradation dimer unless it has independent chromatographic/solution evidence.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4165458/', 'This is a high-priority false-positive guardrail for the LIMS.');
