INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('7a95029a-8398-5ac0-a3f5-48d58489641f', 'DSIP-OLG-02', 'Trp-oxidation-associated oligomer / crosslink family', 'Oxidative oligomer/crosslink', 'variable', 'Generic chemistry candidate', 'Trp oxidation can generate N-formylkynurenine/kynurenine-like products and can accompany nondisulfide crosslinking/aggregation; exact covalent topology and mass are product-specific.', 'At least one Trp plus light/ROS/peroxide/metal stress.', NULL, NULL, NULL, NULL, NULL, 'Search both monomer +O/+2O products and high-mass crosslinked species; MS/MS is needed to identify the actual crosslink.', 'Altered; new long-wave UV bands can appear as the indole ring oxidizes.', 'High-value DAD sentinels: ~320 nm for N-formylkynurenine-type oxidation and ~360 nm for kynurenine-like products; track A320/A280 and A360/A280.', 'Variable; oxidized monomer often shifts separately, while crosslinked oligomers may be later/broader.', 'LC-HRMS/MS; oxidation stress comparison; SEC if size increase is suspected.', 'Do not force a single 2M mass because Trp oxidation/crosslink products are chemically heterogeneous.', 'A 320/360-nm spectral change is evidence of Trp chemistry, not by itself proof that the species is an oligomer.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6213266/', 'Use the complete DAD spectrum: these long-wave oxidation bands can be much more diagnostic than the routine 214/280 channels.');
INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('ac2898d2-fd39-5023-8c37-f994e4634a1d', 'EPITALON-OLG-01', 'ESI noncovalent homodimer / source cluster', 'MS source/association artifact candidate', '2M', 'Instrumental possibility', 'Nonspecific or specific noncovalent association during electrospray/desolvation; may not exist as a discrete solution impurity.', 'Any analyte; risk increases with concentration and soft-source conditions.', 'C28H44N8O18', 780.277357, 0.000000, 781.284633, 391.145955, '[2M+Na]+ = 2M + 22.989218 Da; note [2M+2H]2+ lands at the same nominal m/z as monomer [M+H]+ but has z=2 isotope spacing.', 'Same chromophore; if source-generated there is no independent DAD peak and normalized spectrum is identical to monomer.', 'Require chromatographic evidence. Exact coelution with monomer + identical DAD + source/dilution sensitivity strongly favors an ESI cluster rather than a stored dimer.', 'Usually no separate LC peak if formed in the source.', 'Dilution series and source-energy/CID challenge; SEC only if solution oligomer is suspected.', 'Check coelution/peak shape, isotope spacing, charge state, and whether cluster intensity falls disproportionately after dilution or stronger source declustering.', 'Do not label a 2M ion as a degradation dimer unless it has independent chromatographic/solution evidence.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4165458/', 'This is a high-priority false-positive guardrail for the LIMS.');
INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('48877b85-4549-5524-8d7c-a56e7475e71b', 'GHKCU-OLG-01', 'ESI noncovalent homodimer / source cluster', 'MS source/association artifact candidate', '2M', 'Instrumental possibility', 'Nonspecific or specific noncovalent association during electrospray/desolvation; may not exist as a discrete solution impurity.', 'Any analyte; risk increases with concentration and soft-source conditions.', NULL, NULL, 0.000000, NULL, NULL, '[2M+Na]+ = 2M + 22.989218 Da; note [2M+2H]2+ lands at the same nominal m/z as monomer [M+H]+ but has z=2 isotope spacing.', 'Same chromophore; if source-generated there is no independent DAD peak and normalized spectrum is identical to monomer.', 'Require chromatographic evidence. Exact coelution with monomer + identical DAD + source/dilution sensitivity strongly favors an ESI cluster rather than a stored dimer.', 'Usually no separate LC peak if formed in the source.', 'Dilution series and source-energy/CID challenge; SEC only if solution oligomer is suspected.', 'Check coelution/peak shape, isotope spacing, charge state, and whether cluster intensity falls disproportionately after dilution or stronger source declustering.', 'For fixed-charge salts/coordination complexes, generic neutral-parent 2M arithmetic is intentionally suppressed; define the actual ionized moiety/speciation first. Do not label a 2M ion as a degradation dimer unless it has independent chromatographic/solution evidence.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4165458/', '5-amino-1MQ is a fixed-charge quinolinium salt and GHK-Cu is a coordination complex; source-cluster ion formulas are speciation-dependent. This is a high-priority false-positive guardrail for the LIMS.');
INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('48877b85-4549-5524-8d7c-a56e7475e71b', 'GHKCU-OLG-02', 'Cu(GHK)2 bis-ligand coordination species', 'Metal-mediated association/speciation', '1 Cu : 2 GHK ligands', 'Reported/known', 'A second GHK ligand coordinates the Cu(II) center, giving a 4N bis-ligand coordination state under suitable pH/ligand conditions.', 'GHK excess, pH/ligand environment, Cu(II) coordination equilibrium.', NULL, NULL, NULL, NULL, NULL, 'Ion formula depends on protonation/counterions and LC conditions; treat coordination stoichiometry separately from simple 2M arithmetic.', 'Altered Cu(II) coordination spectrum; full visible DAD is especially valuable.', 'Reported UV-vis behavior shows a ~27-nm blue shift when Cu(GHK)2 forms from the 1:1 Cu(GHK) state. Track visible lambda-max and A580/A605; use 214/254/280/320/400/500/580/605 nm panel.', 'Acidic/organic RP mobile phase may change or dissociate coordination state; a distinct RP peak is not guaranteed.', 'UV-vis/CD/EPR speciation or carefully controlled pH titration; LC-MS only if coordination survives ionization.', 'Mass interpretation is speciation/protonation dependent; visible spectral shift is unusually valuable here.', 'Do not call this a covalent peptide dimer. It is a coordination complex and may be created/destroyed by sample/mobile-phase conditions.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC7503498/', 'This is exactly the kind of case where full-spectrum DAD can outperform a single-wavelength impurity screen.');
