INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('35bb08e8-3e48-5c17-be11-4403741642c8', 'KISSPEPTIN10-OLG-02', 'Solution-phase noncovalent dimer / low-MW oligomer / aggregate', 'Physical association', '2M to nM', 'Generic chemistry candidate', 'Hydrophobic, electrostatic, H-bonding, pi-stacking, lipid-chain association, or fibrillation/self-assembly.', 'Longer peptide, high concentration, hydrophobic/aromatic sequence, lipidation/acylation, agitation, interfaces, pH/ionic-strength stress.', NULL, NULL, NULL, NULL, NULL, 'Native/native-like MS may show nM charge-state series; denaturing RP-LC-MS can dissociate the assembly.', 'Usually very similar normalized DAD spectrum because the covalent chromophores are unchanged. Large particles can create broad long-wavelength apparent absorbance/scattering.', 'Track full-spectrum similarity plus A400/A214 (or long-wave baseline) as a scattering sentinel, but do not use DAD alone to prove oligomerization.', 'May broaden, adsorb, disappear, or dissociate under RP conditions; a discrete RP peak is not guaranteed.', 'SEC (preferably SEC-MALS), DLS, AUC, native MS, or other size-based method.', 'A native-like nM series supports association; disappearance under denaturing LC argues noncovalent rather than covalent.', 'RP-HPLC can under-report noncovalent aggregates because the mobile phase itself may dissociate them.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5665799/', 'Peptide aggregation propensity is highly sequence-, concentration-, pH-, interface-, and formulation-dependent.');
INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('35bb08e8-3e48-5c17-be11-4403741642c8', 'KISSPEPTIN10-OLG-03', 'Oxidative Tyr-Tyr covalent dimer (dityrosine-like crosslink)', 'Covalent oxidative dimer', '2M-H2', 'Generic chemistry candidate', 'Oxidative phenolic radical coupling between Tyr residues on two molecules.', 'At least one Tyr plus oxidative/light/peroxide/metal stress.', 'C126H164N34O28', 2601.245431, -2.015650, 2602.252707, 1301.629992, 'Exact mass alone cannot distinguish dityrosine from other 2H-loss crosslinks; MS/MS localization is needed.', 'Altered: dityrosine-type chemistry can introduce new near-UV absorbance not present in the monomer.', 'High-value DAD clue: new bands near ~290 and ~315 nm in documented Tyr-peptide dimer systems. Track A315/A280 and A315/A214 plus full-spectrum shape.', 'Often more retained/broader due to doubled molecular size and hydrophobic surface, but method-dependent.', 'LC-HRMS/MS plus reduction-insensitive behavior; fluorescence can be highly sensitive for dityrosine if available.', 'Look for ~2M-H2 neutral mass and crosslink-localizing MS/MS fragments.', 'A 2M-H2 mass without the spectral/fragment evidence is not sufficient; disulfide or other oxidative crosslinks can have the same net 2H loss.', 'https://pubmed.ncbi.nlm.nih.gov/1863276/', 'The 290/315-nm clue is mechanism-level evidence from Tyr-containing systems, not a compound-specific occurrence claim.');
INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('35bb08e8-3e48-5c17-be11-4403741642c8', 'KISSPEPTIN10-OLG-04', 'Trp-oxidation-associated oligomer / crosslink family', 'Oxidative oligomer/crosslink', 'variable', 'Generic chemistry candidate', 'Trp oxidation can generate N-formylkynurenine/kynurenine-like products and can accompany nondisulfide crosslinking/aggregation; exact covalent topology and mass are product-specific.', 'At least one Trp plus light/ROS/peroxide/metal stress.', NULL, NULL, NULL, NULL, NULL, 'Search both monomer +O/+2O products and high-mass crosslinked species; MS/MS is needed to identify the actual crosslink.', 'Altered; new long-wave UV bands can appear as the indole ring oxidizes.', 'High-value DAD sentinels: ~320 nm for N-formylkynurenine-type oxidation and ~360 nm for kynurenine-like products; track A320/A280 and A360/A280.', 'Variable; oxidized monomer often shifts separately, while crosslinked oligomers may be later/broader.', 'LC-HRMS/MS; oxidation stress comparison; SEC if size increase is suspected.', 'Do not force a single 2M mass because Trp oxidation/crosslink products are chemically heterogeneous.', 'A 320/360-nm spectral change is evidence of Trp chemistry, not by itself proof that the species is an oligomer.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6213266/', 'Use the complete DAD spectrum: these long-wave oxidation bands can be much more diagnostic than the routine 214/280 channels.');
