INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('2ee9bdcd-97fd-5a6f-9568-c1ff44d1b31d', 'RETATRUTIDE-OLG-02', 'Solution-phase noncovalent dimer / low-MW oligomer / aggregate', 'Physical association', '2M to nM', 'Strongly plausible', 'Hydrophobic, electrostatic, H-bonding, pi-stacking, lipid-chain association, or fibrillation/self-assembly.', 'Longer peptide, high concentration, hydrophobic/aromatic sequence, lipidation/acylation, agitation, interfaces, pH/ionic-strength stress.', NULL, NULL, NULL, NULL, NULL, 'Native/native-like MS may show nM charge-state series; denaturing RP-LC-MS can dissociate the assembly.', 'Usually very similar normalized DAD spectrum because the covalent chromophores are unchanged. Large particles can create broad long-wavelength apparent absorbance/scattering.', 'Track full-spectrum similarity plus A400/A214 (or long-wave baseline) as a scattering sentinel, but do not use DAD alone to prove oligomerization.', 'May broaden, adsorb, disappear, or dissociate under RP conditions; a discrete RP peak is not guaranteed.', 'SEC (preferably SEC-MALS), DLS, AUC, native MS, or other size-based method.', 'A native-like nM series supports association; disappearance under denaturing LC argues noncovalent rather than covalent.', 'RP-HPLC can under-report noncovalent aggregates because the mobile phase itself may dissociate them.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5665799/', 'Lipidated/acylated therapeutic peptides deserve a higher physical-self-association prior; exact behavior must be established empirically for the specific compound/formulation.');
INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('2ee9bdcd-97fd-5a6f-9568-c1ff44d1b31d', 'RETATRUTIDE-OLG-03', 'Oxidative Tyr-Tyr covalent dimer (dityrosine-like crosslink)', 'Covalent oxidative dimer', '2M-H2', 'Generic chemistry candidate', 'Oxidative phenolic radical coupling between Tyr residues on two molecules.', 'At least one Tyr plus oxidative/light/peroxide/metal stress.', 'C442H682N92O136', 9454.927869, -2.015650, 9455.935145, 4728.471211, 'Exact mass alone cannot distinguish dityrosine from other 2H-loss crosslinks; MS/MS localization is needed.', 'Altered: dityrosine-type chemistry can introduce new near-UV absorbance not present in the monomer.', 'High-value DAD clue: new bands near ~290 and ~315 nm in documented Tyr-peptide dimer systems. Track A315/A280 and A315/A214 plus full-spectrum shape.', 'Often more retained/broader due to doubled molecular size and hydrophobic surface, but method-dependent.', 'LC-HRMS/MS plus reduction-insensitive behavior; fluorescence can be highly sensitive for dityrosine if available.', 'Look for ~2M-H2 neutral mass and crosslink-localizing MS/MS fragments.', 'A 2M-H2 mass without the spectral/fragment evidence is not sufficient; disulfide or other oxidative crosslinks can have the same net 2H loss.', 'https://pubmed.ncbi.nlm.nih.gov/1863276/', 'The 290/315-nm clue is mechanism-level evidence from Tyr-containing systems, not a compound-specific occurrence claim.');
INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('12fa5ca0-e848-5d4a-924e-8365c5861203', 'SELANK-OLG-01', 'ESI noncovalent homodimer / source cluster', 'MS source/association artifact candidate', '2M', 'Instrumental possibility', 'Nonspecific or specific noncovalent association during electrospray/desolvation; may not exist as a discrete solution impurity.', 'Any analyte; risk increases with concentration and soft-source conditions.', 'C66H114N22O18', 1502.868145, 0.000000, 1503.875421, 752.441349, '[2M+Na]+ = 2M + 22.989218 Da; note [2M+2H]2+ lands at the same nominal m/z as monomer [M+H]+ but has z=2 isotope spacing.', 'Same chromophore; if source-generated there is no independent DAD peak and normalized spectrum is identical to monomer.', 'Require chromatographic evidence. Exact coelution with monomer + identical DAD + source/dilution sensitivity strongly favors an ESI cluster rather than a stored dimer.', 'Usually no separate LC peak if formed in the source.', 'Dilution series and source-energy/CID challenge; SEC only if solution oligomer is suspected.', 'Check coelution/peak shape, isotope spacing, charge state, and whether cluster intensity falls disproportionately after dilution or stronger source declustering.', 'Do not label a 2M ion as a degradation dimer unless it has independent chromatographic/solution evidence.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4165458/', 'This is a high-priority false-positive guardrail for the LIMS.');
