INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('714a4295-2b1f-5f05-b94f-a253137619d2', 'SERMORELIN-OLG-03', 'Oxidative Tyr-Tyr covalent dimer (dityrosine-like crosslink)', 'Covalent oxidative dimer', '2M-H2', 'Generic chemistry candidate', 'Oxidative phenolic radical coupling between Tyr residues on two molecules.', 'At least one Tyr plus oxidative/light/peroxide/metal stress.', 'C298H490N88O84S2', 6709.621749, -2.015650, 6710.629025, 3355.818151, 'Exact mass alone cannot distinguish dityrosine from other 2H-loss crosslinks; MS/MS localization is needed.', 'Altered: dityrosine-type chemistry can introduce new near-UV absorbance not present in the monomer.', 'High-value DAD clue: new bands near ~290 and ~315 nm in documented Tyr-peptide dimer systems. Track A315/A280 and A315/A214 plus full-spectrum shape.', 'Often more retained/broader due to doubled molecular size and hydrophobic surface, but method-dependent.', 'LC-HRMS/MS plus reduction-insensitive behavior; fluorescence can be highly sensitive for dityrosine if available.', 'Look for ~2M-H2 neutral mass and crosslink-localizing MS/MS fragments.', 'A 2M-H2 mass without the spectral/fragment evidence is not sufficient; disulfide or other oxidative crosslinks can have the same net 2H loss.', 'https://pubmed.ncbi.nlm.nih.gov/1863276/', 'The 290/315-nm clue is mechanism-level evidence from Tyr-containing systems, not a compound-specific occurrence claim.');
