INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('eddb0de3-9b88-5d97-8399-5e9f53156ff0', 'SS31-OLG-02', 'Dmt-Dmt / phenolic oxidative covalent dimer (analogue hypothesis)', 'Covalent oxidative dimer', '2M-H2', 'Generic chemistry candidate', 'Oxidative radical coupling of the 2,6-dimethyltyrosine phenol; mechanistically analogous to Tyr coupling but the exact product spectrum can differ.', 'Dmt residue plus oxidative/light/metal stress.', 'C64H96N18O10', 1276.755681, -2.015650, 1277.762958, 639.385117, 'Use exact mass and MS/MS to localize the crosslink; do not assume dityrosine spectral constants apply unchanged to Dmt.', 'Likely altered phenolic near-UV spectrum.', 'Interrogate 275-400 nm full spectrum. A new 290-320-nm feature would raise this hypothesis, but wavelength assignment must remain empirical for Dmt.', 'Likely later/broader than monomer if the covalent dimer survives RP conditions.', 'LC-HRMS/MS and controlled oxidation comparison.', 'Expected neutral mass relationship ~2M-H2 for simple oxidative C-C/C-O coupling.', 'Treat as an analogy-driven candidate, not a reported SS-31 dimer identity.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10056213/', 'Useful specifically because SS-31 contains the phenolic Dmt residue.');
