INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('82d450b2-de5d-5f1a-9852-1e93fca3fce8', 'THYMOGEN-OLG-02', 'Trp-oxidation-associated oligomer / crosslink family', 'Oxidative oligomer/crosslink', 'variable', 'Generic chemistry candidate', 'Trp oxidation can generate N-formylkynurenine/kynurenine-like products and can accompany nondisulfide crosslinking/aggregation; exact covalent topology and mass are product-specific.', 'At least one Trp plus light/ROS/peroxide/metal stress.', NULL, NULL, NULL, NULL, NULL, 'Search both monomer +O/+2O products and high-mass crosslinked species; MS/MS is needed to identify the actual crosslink.', 'Altered; new long-wave UV bands can appear as the indole ring oxidizes.', 'High-value DAD sentinels: ~320 nm for N-formylkynurenine-type oxidation and ~360 nm for kynurenine-like products; track A320/A280 and A360/A280.', 'Variable; oxidized monomer often shifts separately, while crosslinked oligomers may be later/broader.', 'LC-HRMS/MS; oxidation stress comparison; SEC if size increase is suspected.', 'Do not force a single 2M mass because Trp oxidation/crosslink products are chemically heterogeneous.', 'A 320/360-nm spectral change is evidence of Trp chemistry, not by itself proof that the species is an oligomer.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6213266/', 'Use the complete DAD spectrum: these long-wave oxidation bands can be much more diagnostic than the routine 214/280 channels.');
INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('bdbf402a-0652-50ae-ae12-1a7db3543a6f', 'THYMOSINBETA4-OLG-01', 'ESI noncovalent homodimer / source cluster', 'MS source/association artifact candidate', '2M', 'Instrumental possibility', 'Nonspecific or specific noncovalent association during electrospray/desolvation; may not exist as a discrete solution impurity.', 'Any analyte; risk increases with concentration and soft-source conditions.', 'C424H700N112O156S2', 9920.972634, 0.000000, 9921.979911, 4961.493593, '[2M+Na]+ = 2M + 22.989218 Da; note [2M+2H]2+ lands at the same nominal m/z as monomer [M+H]+ but has z=2 isotope spacing.', 'Same chromophore; if source-generated there is no independent DAD peak and normalized spectrum is identical to monomer.', 'Require chromatographic evidence. Exact coelution with monomer + identical DAD + source/dilution sensitivity strongly favors an ESI cluster rather than a stored dimer.', 'Usually no separate LC peak if formed in the source.', 'Dilution series and source-energy/CID challenge; SEC only if solution oligomer is suspected.', 'Check coelution/peak shape, isotope spacing, charge state, and whether cluster intensity falls disproportionately after dilution or stronger source declustering.', 'Do not label a 2M ion as a degradation dimer unless it has independent chromatographic/solution evidence.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4165458/', 'This is a high-priority false-positive guardrail for the LIMS.');
