INSERT INTO public.nc_oligomer_candidates (nc_compound_id, oligomer_code, name, class, stoichiometry, evidence_level, mechanism_pathway, trigger_motif, molecular_formula, monoisotopic_mass, mass_delta_vs_n_monomer, mz_1plus, mz_2plus, other_diagnostic_ions, expected_normalized_dad, dad_discriminator, rp_hplc_behavior, best_orthogonal_discriminator, lc_ms_discriminator, false_positive_warning, source_url, notes) VALUES ('aa423338-63ec-5d96-935d-6538a703bc27', 'YK11-OLG-01', 'ESI noncovalent homodimer / source cluster', 'MS source/association artifact candidate', '2M', 'Instrumental possibility', 'Nonspecific or specific noncovalent association during electrospray/desolvation; may not exist as a discrete solution impurity.', 'Any analyte; risk increases with concentration and soft-source conditions.', 'C50H68O12', 860.471078, 0.000000, 861.478354, 431.242815, '[2M+Na]+ = 2M + 22.989218 Da; note [2M+2H]2+ lands at the same nominal m/z as monomer [M+H]+ but has z=2 isotope spacing.', 'Same chromophore; if source-generated there is no independent DAD peak and normalized spectrum is identical to monomer.', 'Require chromatographic evidence. Exact coelution with monomer + identical DAD + source/dilution sensitivity strongly favors an ESI cluster rather than a stored dimer.', 'Usually no separate LC peak if formed in the source.', 'Dilution series and source-energy/CID challenge; SEC only if solution oligomer is suspected.', 'Check coelution/peak shape, isotope spacing, charge state, and whether cluster intensity falls disproportionately after dilution or stronger source declustering.', 'Do not label a 2M ion as a degradation dimer unless it has independent chromatographic/solution evidence.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4165458/', 'This is a high-priority false-positive guardrail for the LIMS.');
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, rp_hplc_behavior, dad_behavior, discriminator, guardrail, evidence_level, source_url) VALUES ('OLG-ESI-2M', 'oligomer', 'All analytes in LC-ESI-MS', 'Ion near [2M+H]+, [2M+Na]+, or other 2M adduct that exactly coelutes with monomer', 'ESI noncovalent homodimer/source cluster', '2M plus charge/adduct', 'No independent DAD peak if source-generated; monomer spectrum unchanged', 'Dilute sample and/or increase source declustering/in-source CID; source cluster should fall disproportionately. Verify charge-state isotope spacing and exact coelution.', 'Never count an MS-only 2M ion as a chemical impurity without independent LC/solution evidence.', 'Instrumental possibility', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4165458/');
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, rp_hplc_behavior, dad_behavior, discriminator, guardrail, evidence_level, source_url) VALUES ('OLG-SS-2M', 'oligomer', 'Free-thiol or disulfide-containing peptides', 'Separate LC feature near neutral mass 2M-H2', 'Intermolecular disulfide dimer', '2M - 2.015650 Da', 'Usually parent-like normalized spectrum', 'DTT/TCEP reduction should collapse dimer toward monomer; confirm by HRMS/MS.', '2M-H2 is not unique to disulfides; require reduction sensitivity or crosslink-localizing MS/MS.', 'Strongly plausible / compound-dependent', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10056213/');
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, rp_hplc_behavior, dad_behavior, discriminator, guardrail, evidence_level, source_url) VALUES ('OLG-DITYR', 'oligomer', 'Tyr-containing peptides', 'Separate high-mass feature near 2M-H2 plus new near-UV band', 'Dityrosine-like oxidative dimer', '2M - 2.015650 Da for simple two-H oxidative coupling', 'New ~290 and ~315 nm absorbance is a high-value clue in documented Tyr-peptide dimer systems', 'Track A315/A280 and A315/A214; confirm exact mass and crosslink-localizing MS/MS; reduction should not behave like a disulfide.', 'Wavelength pattern supports mechanism but is not compound-specific proof.', 'Generic chemistry candidate', 'https://pubmed.ncbi.nlm.nih.gov/1863276/');
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, rp_hplc_behavior, dad_behavior, discriminator, guardrail, evidence_level, source_url) VALUES ('OLG-TRP-OX', 'oligomer', 'Trp-containing peptides', 'New 320-360 nm bands, especially on a new/heterogeneous peak', 'Trp oxidation / oxidation-associated crosslink or oligomer family', 'Variable: +O/+2O monomers and product-specific high-mass crosslinks', '~320 nm N-formylkynurenine-type and ~360 nm kynurenine-like bands can emerge', 'Full-spectrum gradient across peak + HRMS/MS; separately score oxidation evidence and oligomer-size evidence.', 'A 320/360-nm band proves neither exact structure nor oligomerization by itself.', 'Generic chemistry candidate', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6213266/');
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, rp_hplc_behavior, dad_behavior, discriminator, guardrail, evidence_level, source_url) VALUES ('OLG-PHYS-SEC', 'oligomer', 'Peptides, especially longer/high-concentration/lipidated species', 'Concentration/time-dependent loss, broad peaks, high-MW species, or SEC early peak', 'Noncovalent dimer/oligomer/aggregate', '2M to nM under native conditions; may dissociate under RP/ESI', 'Normalized spectrum often remains parent-like; particulates can increase long-wavelength apparent absorbance/scattering', 'SEC-MALS/DLS/native MS; compare RP vs SEC recovery and concentration dependence.', 'Do not use absence of a distinct RP-HPLC peak to rule out physical aggregation.', 'Generic chemistry candidate', 'https://www.agilent.com/en/product/biopharma-hplc-analysis/aggregate-fragment-analysis/agilent-bio-sec-5');
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, rp_hplc_behavior, dad_behavior, discriminator, guardrail, evidence_level, source_url) VALUES ('OLG-SPECTRAL-EDGE', 'oligomer', 'All DAD peaks', 'Leading/apex/trailing spectra are not mutually similar', 'Unresolved coelution, crosslink product, degradation component, or baseline/background contribution', 'N/A', 'Systematic spectral gradient across a peak is evidence of heterogeneity', 'Compare absolute signal as well as normalized spectra; use 8-channel ratios and full-spectrum cosine similarity across the peak.', 'Low-signal normalized spectra can exaggerate background; require a minimum absolute signal threshold.', 'Analytical evidence rule', NULL);
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, rp_hplc_behavior, dad_behavior, discriminator, guardrail, evidence_level, source_url) VALUES ('OLG-GHKCU-2L', 'oligomer', 'GHK-Cu', 'Cu/GHK speciation shift with GHK excess or pH change', 'Cu(GHK)2 bis-ligand complex', 'Coordination-state dependent; do not force simple 2M arithmetic', 'Reported ~27 nm blue-shift in Cu(II) visible absorption upon 4N bis-ligand formation', 'Track visible lambda-max and A580/A605 under controlled pH/stoichiometry; orthogonal CD/EPR if needed.', 'Treat as coordination speciation, not peptide covalent dimerization.', 'Reported/known', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC7503498/');
INSERT INTO public.nc_detection_rules (rule_id, kind, applies_to, trigger_feature, candidate_product, rp_hplc_behavior, dad_behavior, discriminator, guardrail, evidence_level, source_url) VALUES ('OLG-SEMA-PHYS', 'oligomer', 'Semaglutide', 'Concentration/time-dependent physical self-association', 'Dimer/trimer, oligomeric micelle, short fibril', '2M/3M/nM noncovalent assemblies', 'Parent-like chromophore spectrum; size must be established orthogonally', 'SEC/DLS/SAXS/native MS; compare concentration and aging.', 'RP-LC may dissociate these species.', 'Reported/known', 'https://pubmed.ncbi.nlm.nih.gov/40355389/');
INSERT INTO public.nc_evidence_rules (rule_id, observation, suggested_score_effect, interpretation_guardrail) VALUES ('EV-001', 'Separate LC peak', '+3', 'A separate chromatographic feature is stronger evidence for a chemical/solution species than an MS-only 2M ion.');
INSERT INTO public.nc_evidence_rules (rule_id, observation, suggested_score_effect, interpretation_guardrail) VALUES ('EV-002', 'Exact coelution of 2M ion with parent and no DAD peak', '-4 to covalent/solution dimer; +4 to ESI-cluster hypothesis', 'Classic source-cluster pattern.');
INSERT INTO public.nc_evidence_rules (rule_id, observation, suggested_score_effect, interpretation_guardrail) VALUES ('EV-003', '10x dilution disproportionately suppresses 2M ion', '+4 ESI-cluster/noncovalent-source hypothesis', 'Cluster abundance can be concentration/source-condition dependent.');
INSERT INTO public.nc_evidence_rules (rule_id, observation, suggested_score_effect, interpretation_guardrail) VALUES ('EV-004', 'Higher source energy suppresses 2M ion without changing LC peak', '+5 ESI-cluster hypothesis', 'Strong instrumental discriminator.');
INSERT INTO public.nc_evidence_rules (rule_id, observation, suggested_score_effect, interpretation_guardrail) VALUES ('EV-005', 'Neutral mass ~2M-H2', '+3 covalent crosslink family', 'Shared by disulfide and some oxidative aromatic crosslinks; not mechanism-specific.');
INSERT INTO public.nc_evidence_rules (rule_id, observation, suggested_score_effect, interpretation_guardrail) VALUES ('EV-006', 'DTT/TCEP collapses candidate to monomer', '+6 disulfide dimer', 'High-value mechanism challenge.');
INSERT INTO public.nc_evidence_rules (rule_id, observation, suggested_score_effect, interpretation_guardrail) VALUES ('EV-007', 'New ~315 nm band / A315-A280 increase', '+5 Tyr/dityrosine-like oxidative crosslink', 'Use only when parent contains Tyr or a related phenolic residue and absolute signal is adequate.');
INSERT INTO public.nc_evidence_rules (rule_id, observation, suggested_score_effect, interpretation_guardrail) VALUES ('EV-008', 'New ~320 nm band', '+4 Trp/N-formylkynurenine oxidation chemistry', 'Supports Trp oxidation; not sufficient to prove oligomerization.');
INSERT INTO public.nc_evidence_rules (rule_id, observation, suggested_score_effect, interpretation_guardrail) VALUES ('EV-009', 'New ~360 nm band', '+4 kynurenine-like oxidation chemistry', 'Supports Trp oxidation; not sufficient to prove oligomerization.');
INSERT INTO public.nc_evidence_rules (rule_id, observation, suggested_score_effect, interpretation_guardrail) VALUES ('EV-010', 'Full-spectrum cosine similarity >0.995 to parent', '+2 physical/noncovalent association; -2 to chromophore-altering oxidative crosslink', 'Threshold should be calibrated empirically per instrument/method.');
INSERT INTO public.nc_evidence_rules (rule_id, observation, suggested_score_effect, interpretation_guardrail) VALUES ('EV-011', 'Systematic leading->apex->trailing spectral change', '+3 unresolved coelution/heterogeneity', 'Require sufficient absolute DAD signal.');
INSERT INTO public.nc_evidence_rules (rule_id, observation, suggested_score_effect, interpretation_guardrail) VALUES ('EV-012', 'SEC high-MW peak with ~2x/3x size', '+6 physical oligomer', 'Especially strong if RP-HPLC does not retain a discrete oligomer peak.');
INSERT INTO public.nc_evidence_rules (rule_id, observation, suggested_score_effect, interpretation_guardrail) VALUES ('EV-013', 'Long-wavelength 400-600 nm baseline/scattering rise', '+2 particulate/large aggregate', 'Non-specific; can also reflect colored impurities/metal complexes.');
INSERT INTO public.nc_evidence_rules (rule_id, observation, suggested_score_effect, interpretation_guardrail) VALUES ('EV-014', 'GHK-Cu visible band blue-shifts ~27 nm with GHK excess', '+5 Cu(GHK)2 speciation', 'Use controlled pH/stoichiometry; acidic RP mobile phase can alter speciation.');
INSERT INTO public.nc_evidence_rules (rule_id, observation, suggested_score_effect, interpretation_guardrail) VALUES ('EV-015', 'MS/MS localizes intermonomer crosslink', '+8 covalent dimer identity', 'Highest-value structural evidence short of authentic standard.');
INSERT INTO public.nc_spectral_panels (nc_compound_id, wavelengths_nm, recommended_range, panel_rationale, recommended_features, parent_dad_guidance, important_note) VALUES ('d81fa563-286b-5cc9-bf05-810e0c6af14c', ARRAY[200,220,240,254,280,315,340,360]::integer[], '200-400 nm (extend if parent chromophore warrants)', 'General aromatic/small-molecule screening panel. Treat the full DAD spectrum and authentic-parent spectrum as primary; do not rely on this generic panel alone for identity.', 'full-spectrum cosine similarity; lambda-max shift; A254/A220; A280/A254; A315/A254; A340/A254; A360/A254', 'Do not hard-code identity to one wavelength; build a reference DAD spectrum and use spectral match + RT.', 'Store all 8 raw channel responses plus the complete normalized and absolute DAD spectrum. The 8 channels are fast features; the full spectrum remains the higher-information evidence.');
INSERT INTO public.nc_spectral_panels (nc_compound_id, wavelengths_nm, recommended_range, panel_rationale, recommended_features, parent_dad_guidance, important_note) VALUES ('decef310-2bb6-536e-8086-b88fbf3f0146', ARRAY[200,214,257,275,290,315,340,400]::integer[], '200-400 nm', 'Backbone + Tyr/Dmt/Phe channels; 290/315 nm pair is useful for oxidative phenolic crosslink screening.', 'A257/A214; A275/A214; A290/A275; A315/A275; A400/A214; full-spectrum cosine similarity; peak-edge spectral gradient', 'Peptide-bond signal at 214 nm; Tyr contributes around 275-280 nm.', 'Store all 8 raw channel responses plus the complete normalized and absolute DAD spectrum. The 8 channels are fast features; the full spectrum remains the higher-information evidence.');
